"""Top View — BFS keeping the first node seen per horizontal distance.

Level order guarantees the first node recorded for a column is the shallowest.

Time: O(n)   Space: O(n)
"""
from collections import deque
from typing import List

if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def topView(self, root) -> List[int]:
        if not root:
            return []
        seen = {}
        queue = deque([(root, 0)])
        while queue:
            node, column = queue.popleft()
            seen.setdefault(column, node.val)
            if node.left:
                queue.append((node.left, column - 1))
            if node.right:
                queue.append((node.right, column + 1))
        return [seen[column] for column in sorted(seen)]
